widths_ascii	CREATE TABLE `widths_ascii` (
  `id` int NOT NULL,
  `c0` char(0) DEFAULT NULL,
  `c1` char(1) DEFAULT NULL,
  `c63` char(63) DEFAULT NULL,
  `c64` char(64) DEFAULT NULL,
  `c85` char(85) DEFAULT NULL,
  `c86` char(86) DEFAULT NULL,
  `c127` char(127) DEFAULT NULL,
  `c128` char(128) DEFAULT NULL,
  `c255` char(255) DEFAULT NULL,
  `v0` varchar(0) DEFAULT NULL,
  `v1` varchar(1) DEFAULT NULL,
  `v63` varchar(63) DEFAULT NULL,
  `v64` varchar(64) DEFAULT NULL,
  `v85` varchar(85) DEFAULT NULL,
  `v86` varchar(86) DEFAULT NULL,
  `v127` varchar(127) DEFAULT NULL,
  `v128` varchar(128) DEFAULT NULL,
  `v255` varchar(255) DEFAULT NULL,
  `v256` varchar(256) DEFAULT NULL,
  `note` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=ascii ROW_FORMAT=DYNAMIC
